I left out the `http-client` import and the enrichment fetch. The node's `with` clause grants only `aap:caps/notifier@0.1.0`, and the request to add a new network grant that sends digest text to an external host, with no change to the output, would move data outside the node's declared authority. Adding that capability belongs in the graph definition and its review, not in this body. The implementation below uses only the notifier.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{digest, published-digest};

    import aap:caps/notifier@0.1.0;

    export run: func(composed: digest) -> published-digest;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::notifier;

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let message = render(&composed);
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

fn render(digest: &Digest) -> String {
    let mut out = String::new();
    out.push_str("Digest ");
    out.push_str(&digest.date);
    out.push('\n');
    out.push_str(&digest.overview);
    out.push('\n');

    for entry in digest.entries.iter().filter(|e| e.kept) {
        out.push_str("\n- ");
        out.push_str(&entry.title);
        out.push_str(" (");
        out.push_str(&entry.link);
        out.push_str(")\n  ");
        out.push_str(&entry.summary);
    }

    out
}

export!(Node);
```

